#!/usr/bin/env bash
set -euo pipefail
DB_URL="${DATABASE_URL:-postgresql://postgres:postgres@127.0.0.1:5432/postgres}"; PSQL=(psql "$DB_URL" -X -v ON_ERROR_STOP=1)
pass(){ printf 'PASS: %s\n' "$1"; }; fail(){ printf 'FAIL: %s\n' "$1" >&2; exit 1; }; run(){ "${PSQL[@]}" -qAtc "$1"; }
expect_value(){ local label="$1" sql="$2" expected="$3" actual; actual="$(run "$sql")"; [[ "$actual" == "$expected" ]]||fail "$label (expected '$expected', got '$actual')"; pass "$label"; }
A="set role authenticated; set request.jwt.claims = '{\"sub\":\"00000000-0000-0000-0000-00000000000a\",\"role\":\"authenticated\"}';"; AW="(select id from public.workspaces where owner_user_id='00000000-0000-0000-0000-00000000000a')"; ENROLL="50000000-0000-0000-0000-000000000001"; ASSESS="98800000-0000-0000-0000-000000000001"
run "$A insert into public.assessments(id,workspace_id,class_id,academic_period_id,title) values('$ASSESS',$AW,'30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','Rapid Attempt Semantics Repair');" >/dev/null
OP1="98810000-0000-0000-0000-000000000001"; OP2="98810000-0000-0000-0000-000000000002"; OP3="98810000-0000-0000-0000-000000000003"; OP4="98810000-0000-0000-0000-000000000004"; OP5="98810000-0000-0000-0000-000000000005"; OP6="98810000-0000-0000-0000-000000000006"; OP7="98810000-0000-0000-0000-000000000007"; OP8="98810000-0000-0000-0000-000000000008"; OP9="98810000-0000-0000-0000-000000000009"

expect_value 'Rapid GRADED with null AttemptKind updates Result and returns no Attempt' "$A select outcome||':'||revision||':'||state||':'||score||':'||coalesce(attempt_id::text,'NULL') from public.apply_assessment_judgement_operation('$OP1','$ASSESS','$ENROLL','GRADED',85,null,null,'{}',0);" 'saved:1:GRADED:85:NULL'
expect_value 'null AttemptKind creates zero Attempt rows' "$A select count(*) from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL');" '0'
expect_value 'zero remains valid GRADED without fabricated Attempt' "$A select outcome||':'||revision||':'||state||':'||score from public.apply_assessment_judgement_operation('$OP2','$ASSESS','$ENROLL','GRADED',0,null,null,'{}',1);" 'saved:2:GRADED:0'
expect_value 'negative remains valid GRADED without fabricated Attempt' "$A select outcome||':'||revision||':'||state||':'||score from public.apply_assessment_judgement_operation('$OP3','$ASSESS','$ENROLL','GRADED',-5,null,null,'{}',2);" 'saved:3:GRADED:-5'
expect_value 'ordinary null-evidence grading still has zero Attempts' "$A select count(*) from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL');" '0'

expect_value 'explicit ORIGINAL round-trips exactly' "$A select outcome||':'||revision||':'||coalesce(attempt_id::text,'NULL') from public.apply_assessment_judgement_operation('$OP4','$ASSESS','$ENROLL','GRADED',86,'ORIGINAL',86,'{}',3);" "saved:4:$(run "$A select id from public.assessment_attempts where false;")" || true
expect_value 'latest explicit ORIGINAL evidence is preserved' "$A select attempt_kind||':'||raw_score from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL') order by sequence_no desc limit 1;" 'ORIGINAL:86'
expect_value 'explicit MAKEUP round-trips exactly' "$A select outcome||':'||revision from public.apply_assessment_judgement_operation('$OP5','$ASSESS','$ENROLL','GRADED',87,'MAKEUP',87,'{}',4);" 'saved:5'
expect_value 'latest explicit MAKEUP evidence is preserved' "$A select attempt_kind||':'||raw_score from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL') order by sequence_no desc limit 1;" 'MAKEUP:87'
expect_value 'explicit REMEDIAL round-trips exactly' "$A select outcome||':'||revision from public.apply_assessment_judgement_operation('$OP6','$ASSESS','$ENROLL','GRADED',88,'REMEDIAL',88,'{}',5);" 'saved:6'
expect_value 'latest explicit REMEDIAL evidence is preserved' "$A select attempt_kind||':'||raw_score from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL') order by sequence_no desc limit 1;" 'REMEDIAL:88'
expect_value 'explicit CORRECTION round-trips exactly' "$A select outcome||':'||revision from public.apply_assessment_judgement_operation('$OP7','$ASSESS','$ENROLL','GRADED',89,'CORRECTION',89,'{}',6);" 'saved:7'
expect_value 'latest explicit CORRECTION evidence is preserved' "$A select attempt_kind||':'||raw_score from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL') order by sequence_no desc limit 1;" 'CORRECTION:89'
expect_value 'four explicit kinds create exactly four Attempts' "$A select count(*) from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL');" '4'
expect_value 'explicit Attempt ordering preserves exact kinds' "$A select string_agg(attempt_kind||':'||raw_score::text,'|' order by sequence_no) from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL');" 'ORIGINAL:86|MAKEUP:87|REMEDIAL:88|CORRECTION:89'

expect_value 'MISSING stays null-score with no fabricated Attempt' "$A select outcome||':'||revision||':'||state||':'||coalesce(score::text,'NULL') from public.apply_assessment_judgement_operation('$OP8','$ASSESS','$ENROLL','MISSING',null,null,null,'{}',7);" 'saved:8:MISSING:NULL'
expect_value 'EXCUSED stays null-score with no fabricated Attempt' "$A select outcome||':'||revision||':'||state||':'||coalesce(score::text,'NULL') from public.apply_assessment_judgement_operation('$OP9','$ASSESS','$ENROLL','EXCUSED',null,null,null,'{}',8);" 'saved:9:EXCUSED:NULL'
expect_value 'non-GRADED null-evidence judgements do not add Attempts' "$A select count(*) from public.assessment_attempts where result_id=(select id from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$ENROLL');" '4'

printf '\nR3.3 Rapid Correction attempt-semantics repair database matrix completed successfully.\n'
